,p_plug_name=>'Unposted Journals'
,p_static_id=>'unposted-journals'
,p_region_template_options=>'#DEFAULT#:t-IRR-region--hideHeader js-addHiddenHeadingRoleDesc'
,p_plug_template=>2103954283454391425
,p_plug_display_sequence=>20
,p_plug_item_display_point=>'ABOVE'
,p_query_type=>'SQL'
,p_plug_source=>wwv_flow_string.join(wwv_flow_t_varchar2(
'SELECT ledger_id,',
'       ledger_name,',
'       period_name,',
'       je_header_id,',
'       je_batch_id,',
'       batch_name,',
'       journal_name,',
'       journal_source,',
'       journal_category,',
'       effective_date,',
'       currency_code,',
'       journal_entered_dr,',
'       journal_entered_cr,',
'       ledger_currency_code,',
'       journal_accounted_dr,',
'       journal_accounted_cr,',
'       ABS(NVL(journal_accounted_dr, 0)',
'         - NVL(journal_accounted_cr, 0)) AS accounted_difference,',
'       balance_type,',
'       journal_description,',
'       batch_description,',
'       batch_balance_status,',
'       severity,',
'       refresh_timestamp',
'FROM   TABLE(',
'           xxme_gl_unposted_pkg.get_journals(:P11_PERIOD_NAME, :P11_DB_LINK)',
'       )',
'ORDER BY ledger_id,',
'         effective_date,',
'         batch_name,',
'         journal_name'))
