,p_query_type=>'SQL'
,p_plug_source=>wwv_flow_string.join(wwv_flow_t_varchar2(
'SELECT accounting_error_id,',
'       application_id,',
'       sla_source,',
'       ledger_id,',
'       ledger_name,',
'       organization_id,',
'       entity_code,',
'       source_transaction_id,',
'       transaction_number,',
'       event_id,',
'       event_type_code,',
'       event_status_code,',
'       process_status_code,',
'       transaction_date,',
'       ae_header_id,',
'       ae_line_num,',
'       accounting_date,',
'       accounting_entry_status_code,',
'       gl_transfer_status_code,',
'       message_number,',
'       error_source_code,',
'       error_message,',
'       error_creation_date,',
'       error_age_days,',
'       exception_type,',
'       severity,',
'       refresh_timestamp',
'FROM TABLE(',
'    xxme_sla_error_drill_pkg.get_errors(',
'        :P42_RUN_PERIOD,',
'        TO_NUMBER(:P42_APPLICATION_ID),',
'        TO_NUMBER(:P42_LEDGER_ID),',
'        TO_NUMBER(:P42_ORG_ID),',
'        :P42_ENTITY_CODE,',
'        :P42_DB_LINK',
'    )',
') e',
'WHERE (:P42_EXCEPTION_TYPE IS NULL OR UPPER(e.exception_type) = UPPER(:P42_EXCEPTION_TYPE))',
'ORDER BY sla_source,',
'         ledger_id,',
'         transaction_date,',
'         event_id,',
'         accounting_error_id'))
